-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('team__parent__tree', ARRAY[to_regclass('"hd"."teams"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"hd"."teams"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."team__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

CREATE FUNCTION authz_gen."hd.workspaces:update:items"(p_row "hd"."workspaces", authz__role name) RETURNS boolean[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT CASE WHEN authz_int."hd.workspaces:seen"("workspaces"."id") THEN ARRAY[
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = "workspaces"."id"), false),
    coalesce((SELECT authz_int.scope_cmd('hd.workspaces', 'update')), false),
    coalesce(true, false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = "workspaces"."id"), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "workspaces"
$f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.workspaces:update:why"(p_row "hd"."workspaces", p_stored boolean) RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."hd.workspaces:update:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update : manage  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.workspaces update'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on hd.workspaces'
    ELSE '  no   the sign-in''s scopes do not allow update on hd.workspaces' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'manage';
  IF NOT v[4] AND p_stored THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('workspace', ((p_row)."id"::text), 'manage') l LIMIT 20;
  END IF;
END $f$;

CREATE FUNCTION authz_gen."hd.users:insert:items"(p_row "hd"."users", authz__role name) RETURNS boolean[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT CASE WHEN authz_int."hd.users:seen"("users"."id") THEN ARRAY[
    coalesce(((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id")
    OR (coalesce((kind = 'customer'), false)
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))))
    AND coalesce((active), false)), false),
    coalesce((SELECT authz_int.scope_cmd('hd.users', 'insert')), false),
    coalesce(coalesce((active), false), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id"), false),
    coalesce((coalesce((kind = 'customer'), false)
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))), false),
    coalesce((EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id")), false),
    coalesce(coalesce((kind = 'customer'), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[7]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "users"
$f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.users:insert:why"(p_row "hd"."users") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."hd.users:insert:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : workspace.manage or ((workspace.work or workspace.connected) and {kind = ''customer''})  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.users insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not insert on hd.users'
    ELSE '  no   the sign-in''s scopes do not allow insert on hd.users' END; END IF;
  IF NOT v[3] THEN RETURN NEXT '  no   the row fails the user type''s where {active}'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'workspace.manage';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("users"."workspace_id")::text AS id FROM (SELECT (p_row).*) AS "users") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('workspace', v_t.id, 'manage') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || '((workspace.work or workspace.connected) and {kind = ''customer''})';
  IF NOT v[5] THEN
    RETURN NEXT CASE WHEN v[6] THEN '    yes  ' ELSE '    no   ' END || '(workspace.work or workspace.connected)';
    RETURN NEXT CASE WHEN v[7] THEN '    yes  ' ELSE '    no   ' END || '{kind = ''customer''}';
  END IF;
END $f$;

CREATE FUNCTION authz_gen."hd.users:update:items"(p_row "hd"."users", authz__role name) RETURNS boolean[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT CASE WHEN authz_int."hd.users:seen"("users"."id") THEN ARRAY[
    coalesce(((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)), false),
    coalesce((SELECT authz_int.scope_cmd('hd.users', 'update')), false),
    coalesce(coalesce((active), false), false),
    coalesce(coalesce("users"."id" = (SELECT authz.uid()), false), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id"), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id"), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[6]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "users"
$f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.users:update:why"(p_row "hd"."users", p_stored boolean) RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."hd.users:update:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update : self or workspace.manage or see_notes  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.users update'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on hd.users'
    ELSE '  no   the sign-in''s scopes do not allow update on hd.users' END; END IF;
  IF NOT v[3] THEN RETURN NEXT '  no   the row fails the user type''s where {active}'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'self';
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'workspace.manage';
  IF NOT v[5] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("users"."workspace_id")::text AS id FROM (SELECT (p_row).*) AS "users") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('workspace', v_t.id, 'manage') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[6] THEN '  yes  ' ELSE '  no   ' END || 'see_notes';
  IF NOT v[6] AND p_stored THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('user', ((p_row)."id"::text), 'see_notes') l LIMIT 20;
  END IF;
END $f$;

